package steps

import (
	"bytes"
	"fmt"
	"os/exec"
	"strings"
)

//truebdd:concept when "operation"
func concept40523ceb26a25e37e78222ac562623f48c38b52711218d94fe5cadea337eebba(state *State, args []string) error {
	exactly, operation, number := args[0], args[1], args[2]

	// The suite's tests run in tests/calc, so the host root the declared CLI
	// documents its commands from is two directories up.
	const hostRoot = "../.."
	const servicePackage = "./services/calc"

	var command string
	switch operation {
	case "halves":
		command = "halve"
	case "doubles":
		command = "double"
	default:
		return fmt.Errorf("the step names no declared operation: %q", operation)
	}

	argv := []string{"run", servicePackage, command}
	if exactly != "" {
		if command != "halve" {
			return fmt.Errorf("the declared %s command takes no --exact flag", command)
		}
		argv = append(argv, "--exact")
	}
	argv = append(argv, number)

	cmd := exec.Command("go", argv...)
	cmd.Dir = hostRoot
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("go %s in %s: %w: %s", strings.Join(argv, " "), hostRoot, err, strings.TrimSpace(stderr.String()))
	}

	// Keep the command's stdout as the output, without the trailing newline the
	// declared interface says it prints after the value.
	state.Output = strings.TrimRight(stdout.String(), "\r\n")
	return nil
}

package steps

import (
	"fmt"
	"regexp"
	"strings"
)

//truebdd:concept then "output"
func concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e(state *State, args []string) error {
	comparison, pattern := args[0], args[1]

	// The When step kept the command's stdout; drop a trailing newline here too so
	// the pattern is matched against the printed value alone, as the binding says.
	output := strings.TrimRight(state.Output, "\r\n")

	expression, err := regexp.Compile(pattern)
	if err != nil {
		return fmt.Errorf("the step's pattern %q is no Go regular expression: %w", pattern, err)
	}

	matched := expression.MatchString(output)

	switch comparison {
	case "matches":
		if !matched {
			return fmt.Errorf("the calculator's output %q has no match for %q", output, pattern)
		}
	case "does not match":
		if matched {
			return fmt.Errorf("the calculator's output %q has a match for %q", output, pattern)
		}
	default:
		return fmt.Errorf("the step names no declared comparison: %q", comparison)
	}

	return nil
}

package steps

func Register(suite Registrar) {

	suite.Step("^the Owner (?:(exactly) )?(halves|doubles) (-?\\d+)$", concept40523ceb26a25e37e78222ac562623f48c38b52711218d94fe5cadea337eebba)

	suite.Step("^the calculator's output (matches|does not match) (.+)$", concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e)
}
